case "${1:-}" in
  record-review) shift; cmd_record_review "$@" ;;
  status)        cmd_status ;;
  advance-arm)   shift; cmd_advance_arm "$@" ;;
  record-quota-lockout) shift; cmd_record_quota_lockout "$@" ;;
