  reconcile)     shift; [[ -f "${LEDGER_BIN}" ]] && exec bash "${LEDGER_BIN}" reconcile "$@"; exit $? ;;
  -h|--help)     usage ;;
  *)             cmd_resolve "$@" ;;
esac

